export type SourceId = 'gm' | 'player' | 'trinity' | 'talagaad-adventures' | 'starter-kit';

export interface Source {
  id: SourceId;
  title: string;
  icon: string;
}

export const sources: Source[] = [
  { id: 'gm', title: 'Руководство ведущего', icon: 'Crown' },
  { id: 'player', title: 'Руководство игрока', icon: 'UserRound' },
  { id: 'trinity', title: 'Жажда троицы', icon: 'Compass' },
  { id: 'talagaad-adventures', title: 'Приключения в Талагааде', icon: 'Compass' },
  { id: 'starter-kit', title: 'Стартовый набор', icon: 'Package' },
];

export interface CreatureAttack {
  name: string;
  range: string;
  formula: string;
  damage: string;
  rounds: string;
  traits?: string;
}

export interface CreatureAbility {
  name: string;
  description: string;
  descriptionLinks?: StatLink[];
  linkEntryId?: string;
}

export interface CreatureEquipmentItem {
  name: string;
  linkEntryId?: string;
}

export interface CreatureStatBlock {
  characteristics: { code: string; value: number }[];
  speed: string;
  wounds: number | string;
  type: string;
  skills: string[];
  attacks: CreatureAttack[];
  defenses: string[];
  abilities: CreatureAbility[];
  equipment?: CreatureEquipmentItem[];
}

export interface OpinionQuote {
  quote: string;
  author: string;
  linkEntryId?: string;
}

export interface StatLink {
  // Точная подстрока в значении характеристики, которая станет ссылкой
  match: string;
  // Либо ссылка на конкретную запись кодекса...
  entryId?: string;
  // ...либо ссылка, открывающая окно со всеми записями раздела (например «Происхождения»)
  sectionId?: SectionId;
}

export interface CalloutItem {
  text: string;
  links?: StatLink[];
}

export interface Callout {
  title: string;
  items: (string | CalloutItem)[];
}

export interface StatRowValue {
  label: string;
  value: string;
  links?: StatLink[];
}

export interface CodexEntry {
  id: string;
  title: string;
  section: SectionId;
  source: SourceId;
  summary: string;
  tags?: string[];
  meta?: string;
  category?: ItemCategoryId;
  stats?: StatRowValue[];
  subgroup?: string;
  creatureStats?: CreatureStatBlock;
  portrait?: string;
  otherOpinions?: OpinionQuote[];
  relatedEntryIds?: string[];
  callouts?: Callout[];
  // Ссылки на подстроки внутри текста summary (аналогично links в StatRowValue)
  summaryLinks?: StatLink[];
}

export interface Subgroup {
  id: string;
  title: string;
  sectionId: SectionId;
  sourceId: SourceId;
  parentId?: string;
}

