    summary: 'Некоторые модификаторы проверок имеют особое значение.\n\nЕсли ваш выбор был неосмотрительным, или на вас повлияли тёмные силы, а надежда почти угасла, ваша проверка считается мрачной. И наоборот, если ситуация резко изменилась в вашу пользу, проверка становится славной. Эти модификаторы применяются крайне редко — обычно только при катастрофической неудаче или под влиянием могущественных мистических сил (магии, божественного вмешательства или капризов судьбы).\n\nВ отличие от модификаторов костей, мрачные и славные эффекты не суммируются. Они действуют по принципу «всё или ничего»: либо применяются, либо нет. Если проверка по какой‑либо причине оказывается одновременно и мрачной, и славной, эти два эффекта взаимно нейтрализуются — переброс костей не производится.',
