    summary: 'Если в проверке участвуют два соперничающих персонажа, каждый из них проводит базовую проверку. Побеждает тот, кто набрал большее количество успехов.\n\nЕсли количество успехов равно, победитель определяется по приоритетам: инициатор встречной проверки, тот, кто пытается изменить текущее положение дел, или обладатель более высокого значения навыка. В проверках атаки при ничьей преимущество всегда на стороне атакующего. Если ни один из соперников не набрал успехов, ничья не рассматривается: оба провалились, и ситуация для всех участников становится только хуже.\n\nЧтобы вычислить дополнительные эффекты во встречной проверке, определите разницу в количестве успехов между победителем и проигравшим, а затем сверьтесь с таблицей результатами проверок. Победа, достигнутая при ничьей, приравнивается к незначительному успеху.\n\nПомните, что дополнительные эффекты не действуют на проверки атаки или любые проверки, направленные на их отражение.',
