    summary: 'Ваше воспитание прошло в гномьих караках — древних подземных твердынях стойких кланов.\n\nВы владеете счётом, можете общаться на кхазалиде и умеете читать и писать на клинкархуне (гномий рунический алфавит).\n\nВы осведомлены о структуре своего клана: владыках, твердынях, ремёслах, героических деяниях и неразрешённых обидах.\n\nВы знаете, как правильно проявлять уважение к Грунгни, Гримниру, Валайе и другим Богам‑Предкам.\n\nВы также способны распознавать творения злых существ — таких как орки, гоблины, нежить и порождения Хаоса, — а также жалких подземных существ, которые для людей остаются мифами.',
