    summary: 'Вы обладаете полным знанием определённого города, порта, поселения, гномьего карака или крупной крепости — на его территории вы никогда не заблудитесь.\n\nВы точно знаете, где найти персонажа ведущего, готового предоставить ночлег, приобрести или продать редкие товары, а также помочь в решении любых стандартных проблем.\n\nВам известны имена и лица ключевых общественных деятелей этого места, его недавняя история, мифы об основании, потенциальные угрозы, а также необычные законы и обычаи местных жителей.\n\nВы отлично осведомлены о тонкостях городской жизни, которая резко контрастирует с деревенской: в городе праздношатающиеся могут появляться на улицах даже в торговый день.\n\nПрибыв в новый город, вы быстро определяете, где можно найти еду, жильё или временную работу. У вас есть интуитивная способность распознавать неблагополучные районы или места, где ваше появление будет нежелательным.',
