    summary: 'Вы выросли в Ультуане — священной земле эльфов и королевстве Королей‑Фениксов.\n\nВы владеете эльтарином (эльфийским языком), обладаете хорошими навыками в арифметике, а также разбираетесь в истории и географии известного мира. Вам известны имена и гербы десяти принцев Ультуана, и вы внимательно следите за политическими интригами, которые плетут их агенты.\n\nВы знакомы с именами и заповедями эльфийского пантеона, в частности с Кадаев, правящих на небесах. Вы способны распознать творения злых существ — таких как орки, гоблины и ожившие мертвецы, — но особенно настороженно относитесь к угрозе Хаоса и к осквернению, которое он несёт.',
