    summary: 'Вы хорошо разбираетесь в дикой фауне Старого Света и знаете распространённые методы охоты на этих зверей, а также способы избежать с ними столкновения.\n\nВы осведомлены о том, какие существа поддаются одомашниванию, и знакомы с процедурой их приручения. Кроме того, вы умеете обрабатывать раны животных.\n\nПо следам вы способны распознать большинство видов животных, а осмотрев тушу, можете приблизительно определить причину и время смерти.',
