    id: 'o1', section: 'origins', source: 'player', title: 'Бретонец',
    summary: 'На западе Империи, между Серыми горами и Срединным морем, раскинулось королевство Бретония. Величественные белоснежные шпили городов Бретонии устремляются к небесам, напоминая древние башни высших эльфов, выстроившиеся вдоль побережья. Однако это впечатление обманчиво: за парадным фасадом скрываются города, полные угнетённых крестьян‑рабочих, страдающих от болезней и нищеты.\n\nБретония — страна множества феодальных владений, где крестьяне трудятся на благо знати. Местные феодалы чтут идеалы чести и рыцарства. Большинство из них относится к подданным как к ценному, но податливому ресурсу. Однако, когда королевству угрожает вторжение орков или набеги норскийцев, знать с гордостью берёт на себя ответственность и выступает против опасности. Оседлав могучих боевых коней, в сияющих доспехах и с острыми мечами, бретонские рыцари становятся героями песен всего Старого Света. При этом в этих песнях куда меньше внимания уделяется солдатам‑крестьянам, которые сопровождают рыцарей и несут на себе всю тяжесть военных походов, питаясь лишь надеждой на возвращение к мирному труду на своих полях.\n\nЭто обнищавшее величие объединено общей верой в Деву Озера — богиню, чья сущность пронизывает все сферы бретонской жизни. Любой труд и любая жертва считаются оправданными, если они служат Деве. Бретонцы редко покидают родину — разве что ради священных походов или, изредка, в силу изгнания. Поскольку изгнанные рыцари нередко берут с собой крестьян, на имперских кораблях порой можно встретить бретонцев разных сословий — одновременно восхищённых и напуганных мощью этой нации и её суровыми жителями.',
