    id: 'o2', section: 'origins', source: 'player', title: 'Имперец',
    summary: 'Империя находится в самом центре Старого Света. Несмотря на свою раздробленность, она продолжает оставаться величайшей силой среди всех человеческих королевств. Её граждане прекрасно осознают это — порой даже с излишним самодовольством.\n\nСвирепые враги поджидают на границах Империи и внутри неё. И хотя интриги жаждущих власти курфюрстов и менее знатных дворян почти привели к её падению, непоколебимая вера в Империю, основанную Сигмаром, позволяет ей противостоять любым испытаниям.\n\nЖители Империи существенно отличаются друг от друга. Те, кто родился в городах, могут наслаждаться относительной безопасностью: они обучаются ремёслам и лишь наблюдают за формированиями могучих армий, отправляющихся на далёкие войны. В отличие от них, люди, живущие за пределами высоких стен городов — в изолированных деревнях Великого леса или на обдуваемых ветрами северных побережьях, — хорошо осознают, что опасность всегда на пороге. Появление армии на горизонте обычно становится предвестником беды.\n\nНезависимо от происхождения, многие люди склонны к суеверию: они крепко держатся за талисманы древних и новых богов, проклинают ведьм в благоприятные времена, но обращаются к тем, кто практикует запретную магию, когда надвигается опасность. Среди них встречаются и честные, и принципиальные герои, но на каждую благородную личность приходится как минимум один безжалостный злодей, прячущийся в тенях.',
