    summary: 'Когда‑то высшие эльфы были владыками мира смертных. Империя Королей‑Фениксов охватывала целые континенты, поддерживаемая мощью их армий и магическим искусством. Их подвиги вошли в легенды, а возведённые ими города и поныне сверкают алебастром — как памятники гордости и величия. Однако века не пощадили их: история высших эльфов — это череда взлётов и трагедий.\n\nСегодня владения высших эльфов ограничены королевствами Ультуана и несколькими разбросанными колониями, а руины их былого величия мрачно напоминают о непостоянстве всего сущего. На протяжении долгих веков они держались в стороне от внешнего мира, отказавшись от значительной части своих земель после разрушительной войны с гномами. Хотя исследовательские и торговые экспедиции не прекращались, лишь недавно, под руководством Короля‑Феникса Финубара Мореплавателя, высшие эльфы вновь заинтересовались внешними делами. Они разместили гарнизоны на островах у берегов Старого Света и начали налаживать отношения с человеческими королевствами — теперь дипломатов и купцов высших эльфов можно встретить по всей Империи.\n\nВысшие эльфы по‑прежнему горды, долгожительны и искусны в войне и магии, но их былое величие, без сомнения, осталось в прошлом. Несмотря на разброд, вызванный войной, и уход на островной континент Ультуан, они не утратили чувства ответственности за мир, которому когда‑то помогли возникнуть.',
