    id: 'o4', section: 'origins', source: 'player', title: 'Гном',
    summary: 'Гномы — гордый народ, славящийся талантливыми ремесленниками и могущественными воинами. Некогда они контролировали значительную часть Старого Света, но разрушительная война с эльфами и последующие столетия бедствий серьёзно ослабили их могущество. Многие родовые горные твердыни были потеряны — так образовалась обширная гномья диаспора.\n\nВ тех твердынях, что выдержали тысячелетия бедствий, упрямый дух гномов по‑прежнему не угасает. Караз Анкор — так они именуют своё горное королевство — остаётся столь же решительным и стойким, как и в прежние времена. Для гномов древние жилища — оплот чести, силы и мужества в мире, охваченном тёмными силами. Империя людей для них — лишь самоуверенный новичок: нация, едва ли достигшая цивилизации, и то лишь благодаря гномьей помощи.\n\nТем не менее древний альянс между людьми и гномами по‑прежнему крепок. Многие гномы нашли новые жилища в городах и селениях Империи, где их общины пользуются уважением и определённой свободой. Их трудолюбие и мастерство принесли Империи немалую пользу. Гномов, обосновавшихся в Империи, сородичи называют имперскими гномами.\n\nГномы легко впадают в ярость, мелочны в обидах и не прощают врагов. Но если удаётся заслужить их расположение, они становятся надёжными друзьями и союзниками — и Империя не раз убеждалась в этом на деле.',
