    summary: 'Привилегированный доступ к продовольственным резервам Хюгельштрока наделил Бодстура внушительным телосложением и неоспоримым авторитетом в общине. В его власти решать, кому придётся тащить пшеницу на верхний этаж мельницы, кто будет вращать колесо, приводящее в движение жернова, и кому достанется пересыпать готовую муку в истёртые до дыр мешки. Более того, Бодстур ведает содержанием будущих жертв: их держат взаперти в естественном подвале под мельницей. Он откровенно упивается тем, что изводит узников до самого часа жертвоприношения. Затем, пользуясь своей недюжинной силой, он лично уводит их в условленное место в чаще леса. Как главный каратель Пеффера, Бодстур держит остальных жителей в ежовых рукавицах — на случай, если кто-то осмелится ослушаться или усомниться в воле старейшины.',
