          description: 'Моенбрук — маг 2-го уровня. Он может добавлять бонусные кости к проверкам сотворения заклинаний, при этом равное количество костей уходит в его Пул магической отдачи. Раз в раунд он может провести встречную проверку силы воли против сотворения заклинания на дальней дистанции: все кости, на которых выпало 9, добавляются в его Пул магической отдачи.\n\nМоенбрук помнит следующие заклинания:\n\nВосстание из реки (ПС 1). Ряды мёртвых пополняются терзаемыми душами тех, кто был похоронен без обряда. Цель — призрачное воинство на дальней дистанции от реки Талабек. Количество успехов, необходимых для победы над призрачным воинством, увеличивается на значение [могущества] заклинания.\n\nУтянуть в пучину (ПС 1). Цель — враг на дальней дистанции от реки Талабек. Цепкие руки мстительных призраков тянут его на одну зону ближе к реке — Моенбрук сам выбирает направление. Если заклинание затягивает персонажа в реку, духи погружают его голову под воду. Персонаж должен пройти проверку стойкости, чтобы противостоять опасности утопления; рейтинг опасности равен значению [могущества] заклинания.\n\nПризрачная форма (ПС 2). Духи вселяются в смертное тело Моенбрука и переносят его через призрачный мир. На количество ходов, равное значению [могущества] заклинания, Моенбрук получает способность эфирный.',
